<?php
declare(strict_types=1);
function token_role_scopes(string $role): array {return $role==='listener'?['read']:(in_array($role,['owner','admin'],true)?['read','upload','organise','admin']:['read','upload','organise']);}
function token_required_scope(string $method,string $path): ?string {
    if($path==='/api/auth/me'&&$method==='GET')return 'read';if(preg_match('~^/api/(?:auth(?:/|$)|setup(?:/|$)|sessions(?:/|$)|tokens(?:/|$))~',$path))return null;if(str_starts_with($path,'/api/admin/')||str_starts_with($path,'/api/invites'))return 'admin';if(in_array($method,['GET','HEAD'],true))return 'read';if(str_starts_with($path,'/api/uploads')||preg_match('~^/api/tracks/[^/]+/peaks$~',$path))return 'upload';return 'organise';
}
function bearer_auth(PDO $db): ?array {
    $header=$_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??'';if(!str_starts_with($header,'Bearer '))return null;$raw=substr($header,7);if(!preg_match('/^wh_live_[A-Za-z0-9_-]{43}$/D',$raw))fail('unauthenticated','This API token is unavailable or expired.',401);$token=query_one($db,'SELECT id,user_id,name,scopes,created_at,last_used_at,expires_at FROM api_tokens WHERE token_hash=? AND revoked_at IS NULL AND(expires_at IS NULL OR expires_at>?)',[hash('sha256',$raw),now_ms()]);$user=$token?query_one($db,"SELECT * FROM users WHERE id=? AND status='active'",[$token['user_id']]):null;if(!$token||!$user)fail('unauthenticated','This API token is unavailable or expired.',401);rate_limit($db,'api-token',600,60,$token['id']);$scopes=json_decode($token['scopes'],true);$path=app_relative_path(rawurldecode(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/'))??'/';$required=token_required_scope($_SERVER['REQUEST_METHOD']??'GET',$path);if(!$required||!is_array($scopes)||!in_array($required,$scopes,true)||!in_array($required,token_role_scopes($user['role']),true))fail('insufficient_scope',$required?'This token needs the '.$required.' scope.':'Use a signed-in browser for account security settings.',403);if(!$token['last_used_at']||(int)$token['last_used_at']<now_ms()-600000)execute($db,'UPDATE api_tokens SET last_used_at=? WHERE id=?',[now_ms(),$token['id']]);return ['user'=>public_user($user),'session'=>['id'=>$token['id'],'user_id'=>$user['id'],'device_label'=>$token['name'],'created_at'=>$token['created_at'],'last_seen_at'=>now_ms(),'expires_at'=>$token['expires_at']??9007199254740991],'token'=>['id'=>$token['id'],'name'=>$token['name'],'scopes'=>$scopes]];
}
function tokens_routes(PDO $db,array $auth,string $path,string $method): bool {
    if($path!=='/api/tokens'&&!preg_match('~^/api/tokens/[0-9A-HJKMNP-TV-Z]{26}$~',$path))return false;if(isset($auth['token']))fail('forbidden','Use a signed-in browser to manage API tokens.',403);
    if($path==='/api/tokens'&&$method==='GET'){$rows=query_all($db,'SELECT id,name,prefix,scopes,created_at,last_used_at,expires_at,revoked_at FROM api_tokens WHERE user_id=? ORDER BY created_at DESC LIMIT 2000',[$auth['user']['id']]);foreach($rows as &$row)$row['scopes']=json_decode($row['scopes'],true);reply(['items'=>$rows,'nextCursor'=>null]);}
    if($path==='/api/tokens'&&$method==='POST'){$input=body();$name=input_text($input['name']??null,'Token name',100,true);$scopes=$input['scopes']??null;$allowed=token_role_scopes($auth['user']['role']);if(!is_array($scopes)||!array_is_list($scopes)||!count($scopes)||count($scopes)>4||array_diff($scopes,$allowed))fail('forbidden','Choose scopes allowed by your account role.',403);$scopes=array_values(array_unique($scopes));$days=$input['expiresDays']??30;if(!is_int($days)||$days<1||$days>365)fail('validation','Choose an expiry from 1 to 365 days.');$raw='wh_live_'.token();$id=ulid();$prefix=substr($raw,0,16);$now=now_ms();$expires=$now+$days*86400000;execute($db,'INSERT INTO api_tokens(id,user_id,name,token_hash,prefix,scopes,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$auth['user']['id'],$name,hash('sha256',$raw),$prefix,json_encode($scopes,JSON_THROW_ON_ERROR),$now,$expires]);reply(['id'=>$id,'name'=>$name,'prefix'=>$prefix,'token'=>$raw,'scopes'=>$scopes,'created_at'=>$now,'expires_at'=>$expires],201);}
    if($path!=='/api/tokens'&&$method==='DELETE'){execute($db,'UPDATE api_tokens SET revoked_at=? WHERE id=? AND user_id=? AND revoked_at IS NULL',[now_ms(),basename($path),$auth['user']['id']]);reply(['ok'=>true]);}return false;
}
